function roleDetail(r){state.role=r;const issue=ref.validation.missingParents.some(x=>x.code===r.code),conflicts={'214101':['مهندس صناعي','Industrial engineer'],'214601':['مهندس تعدين','Mining engineer']};el('role').innerHTML='<div class="ent-role-detail"><span class="ent-code">'+r.code+'</span><h3 lang="ar">'+esc(r.titleAr)+'</h3><p lang="ar">'+ancestry(r.parent).map(x=>esc(x.titleAr)).join(' / ')+'</p><p>'+t('المصدر: الدليل المرفق، يناير 2019، صفحة ','Source: supplied January 2019 directory, page ')+r.sourcePage+'</p>'+(issue?note('تنبيه في المصدر: لا تظهر الوحدة الأب '+r.parent+' في هذا الإصدار. يلزم تحقق موثق قبل الاعتماد.','Source issue: parent unit '+r.parent+' is absent in this edition. Documented verification is required.'): '')+(conflicts[r.code]?note('تصحيح مرجعي: كانت العينة السابقة تعرض «'+conflicts[r.code][0]+'» لهذا الرمز. العنوان أعلاه هو الوارد في الملف المرفق.','Reference correction: the previous sample used “'+conflicts[r.code][1]+'” for this code. The title above is the one in the supplied edition.'):'')+'<div class="action-row">'+button('use-reference',t('إنشاء منصب على هذا المرجع','Design a position using this reference'),true)+'</div></div>';el('use-reference').onclick=()=>{resetGuidedPosition();state.draft={...state.draft,title:r.titleAr,occupationCode:r.code,occupationRelease:ref.id,provisional:false};state.dirty=true;setTab('create');};}
