function textField(k,area=true){const n=fieldNames[k]||[k,k],v=state.draft[k]??'';return '<label class="ent-field">'+t(...n)+(C.required.includes(k)?' <span aria-hidden="true">*</span>':'')+(area?'<textarea dir="auto" data-field="'+k+'" rows="'+(k==='responsibilities'?4:2)+'" maxlength="4000">'+esc(v)+'</textarea>':'<input dir="auto" data-field="'+k+'" value="'+esc(v)+'" maxlength="300">')+'</label>';}
