 el('export-json').onclick=()=>run(async()=>download(JSON.stringify(me?await api('/positions/'+id+'/export/json'):p,null,2),p.internalCode+'.json'));for(const f of ['pdf','docx','xlsx','receipt'])if(el('export-'+f))el('export-'+f).onclick=()=>run(async()=>{if(!me&&f==='pdf'){await draftPDF(p.content,p,el('export-pdf'));return;}const v=await api('/positions/'+id+'/export/'+f+'?lang='+lang,'GET',null,f!=='receipt');download(f==='receipt'?JSON.stringify(v,null,2):v,p.internalCode+'.'+(f==='receipt'?'receipt.json':f));});
