 const legacy=entry.legacyApprovedRecord===true&&position.activeRevision===position.revision&&entry.positionId===position.id&&entry.revision===position.revision&&(!result.positionId||result.positionId===position.id)&&(!result.positionRevision||result.positionRevision===position.revision);
 if(!(normal||reused||legacy)||(!(result.committee?.status==='approved-committee-record')&&!legacy))return null;
 const grade=String(result.band?.id||'').trim();if(!grade)return null;const content={...position.content};for(const key of ['salaryGrade','salaryMin','salaryMax','salaryCurrency','salaryPeriod','salarySource','evaluationSummary','evaluatedPositionId','evaluatedPositionRevision'])delete content[key];
