function institutionGradeFor(points){const profile=window.MiyarInstitutionProfile?.read?.(),scored=(profile?.gradeStructure?.grades||[]).filter(g=>Number.isInteger(g.minPoints)&&Number.isInteger(g.maxPoints));if(!scored.length)return {configured:false,grade:null};const g=scored.find(x=>x.minPoints<=points&&points<=x.maxPoints)||null;return {configured:true,grade:g,label:g?g.id+' · '+(lang==='ar'?g.labelAr:g.labelEn):'',version:profile.version||null};}
function gradeBreakdown(f,r,answers){return '<table class="ent-grade-breakdown"><thead><tr><th scope="col">'+t('العامل','Factor')+'</th><th scope="col">'+t('المستوى المختار','Selected level')+'</th><th scope="col">'+t('الوزن','Weight')+'</th><th scope="col">'+t('النقاط الموزونة','Weighted points')+'</th></tr></thead><tbody>'+f.factors.map(x=>{const level=x.levels.find(l=>l.id===String(answers[x.id])),row=(r.breakdown||[]).find(b=>b.factor===x.id);return '<tr><td>'+esc(lang==='ar'?x.labelAr:x.labelEn)+'</td><td>'+esc(level?(lang==='ar'?level.labelAr:level.labelEn):'—')+'</td><td>'+x.weight+'%</td><td>'+(row?count(Math.round(row.points)):'—')+'</td></tr>';}).join('')+'</tbody></table>';}
function gradeCommitteeSummary(committee){if(!committee)return '';const pending=committee.status==='awaiting-second-authenticated-evaluator',approved=committee.status==='approved-committee-record',legacy=committee.status==='legacy-approved-record',members=committee.evaluations||committee.members||[],diffs=committee.differences||[],local=committee.verified===false,label=t(pending?'بانتظار مقيم ثانٍ مسجل':legacy?'اعتماد تاريخي بمقيم واحد؛ لا يفي بسياسة اللجنة الحالية':approved?'لجنة تقييم مؤسسية معتمدة':local?'تقييم محلي غير معتمد':'اكتمل تسجيل المقيمين؛ راجع الفروق',pending?'Waiting for a second authenticated evaluator':legacy?'Historical single-evaluator approval; does not meet the current committee policy':approved?'Approved organization committee record':local?'Unapproved local committee record':'Evaluators recorded; review differences');return '<div class="ent-note"><strong>'+t('لجنة التقييم: ','Evaluation committee: ')+label+'</strong><p>'+t('عدد المقيمين: ','Evaluator count: ')+count(committee.count||members.length)+' / '+count(committee.minimumEvaluators||2)+'</p>'+members.map(x=>'<p>'+esc(x.evaluatorId)+' · '+count(x.points)+' · '+esc(x.grade||'')+'</p>').join('')+(local?'<p>'+t('فرق النقاط: ','Points difference: ')+count(committee.pointsDifference||0)+'</p>':'')+diffs.map(d=>'<p>'+esc(d.firstEvaluatorId)+' / '+esc(d.secondEvaluatorId)+' · '+t('فرق النقاط: ','Points difference: ')+count(d.pointsDifference)+' · '+t('اختلاف الدرجة: ','Grade differs: ')+t(d.gradeDifference?'نعم':'لا',d.gradeDifference?'Yes':'No')+'</p><ul>'+(d.factorDifferences||[]).map(x=>'<li>'+esc(x.factor)+': '+count(x.firstLevel)+' / '+count(x.secondLevel)+'</li>').join('')+'</ul>').join('')+'</div>';}
