function gradeCommitteeHTML(f){return '<details open><summary>'+t('لجنة تقييم محلية — مقيمان على الأقل','Local evaluation committee — at least two evaluators')+'</summary>'+note('تُسجّل هويات المقيمين وتقييماتهم كبيانات محلية غير متحققة. الاعتماد المؤسسي يتطلب مقيمين مستقلين مسجلين على الخادم.','Locally declared evaluator identities and ratings are unverified. Organization approval requires independent authenticated server evaluators.')+'<div class="ent-form-grid">'+[0,1].map(i=>'<label class="ent-field">'+t('مرجع المقيم '+(i+1),'Evaluator '+(i+1)+' reference')+'<input data-evaluator="'+i+'" minlength="3" maxlength="120"></label>').join('')+'</div><p>'+t('عوامل التقييم أعلاه تخص المقيم الأول. أدناه تقدير المقيم الثاني، لتسجيل الفروق.','The factors above are the first evaluator’s ratings. Record the second evaluator’s independent ratings below to preserve differences.')+'</p><div class="ent-grade-grid">'+f.factors.map(x=>'<label class="ent-field">'+esc(lang==='ar'?x.labelAr:x.labelEn)+'<select data-second-factor="'+esc(x.id)+'"><option value="">'+t('اختر مستوى المقيم الثاني','Choose the second rating')+'</option>'+x.levels.map(l=>'<option value="'+esc(l.id)+'">'+esc(lang==='ar'?l.labelAr:l.labelEn)+'</option>').join('')+'</select></label>').join('')+'</div></details>';}
